/**
 * Small helpers extracted from sim to keep files under limits.
 */
import type { Building, EntityId, GameMap, Vec2, WorldState } from './types';
import { BUILDING_FOOTPRINTS, WALKABLE_TILES } from './constants';
import { dist, floorVec, tileCenter } from './utils';

export function getBuildingCenter(b: Building): Vec2 {
  return { x: b.footprint.x + b.footprint.w / 2, y: b.footprint.y + b.footprint.h / 2 };
}

export function isTileBaseWalkable(map: GameMap, tx: number, ty: number): boolean {
  if (tx < 0 || tx >= map.width || ty < 0 || ty >= map.height) return false;
  const t = map.tiles[ty][tx];
  return WALKABLE_TILES.has(t);
}

export function isTileWalkable(map: GameMap, tx: number, ty: number, buildings: Map<EntityId, Building>): boolean {
  if (!isTileBaseWalkable(map, tx, ty)) return false;
  for (const b of buildings.values()) {
    if (!b.isComplete) continue;
    const fp = b.footprint;
    if (tx >= fp.x && tx < fp.x + fp.w && ty >= fp.y && ty < fp.y + fp.h) return false;
  }
  return true;
}

export function isPositionOccupied(state: WorldState, tx: number, ty: number, exclude?: EntityId): boolean {
  for (const u of state.units.values()) {
    if (u.id === exclude) continue;
    const ux = Math.floor(u.pos.x), uy = Math.floor(u.pos.y);
    if (ux === tx && uy === ty) return true;
  }
  return false;
}

export function findNearestWalkable(map: GameMap, buildings: Map<EntityId, Building>, target: Vec2, maxRadius = 8): Vec2 | null {
  const tx = Math.floor(target.x), ty = Math.floor(target.y);
  if (isTileWalkable(map, tx, ty, buildings) && !isPositionOccupied({ units: new Map(), buildings } as any as WorldState, tx, ty)) {
    return tileCenter(tx, ty);
  }
  for (let r = 1; r <= maxRadius; r++) {
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (Math.abs(dx) < r && Math.abs(dy) < r) continue;
        const x = tx + dx, y = ty + dy;
        if (isTileWalkable(map, x, y, buildings) && !isPositionOccupied({ units: new Map(), buildings } as any as WorldState, x, y)) {
          return tileCenter(x, y);
        }
      }
    }
  }
  return null;
}

export function updateSupplyCaps(state: WorldState) {
  for (let f = 0; f < 2; f++) {
    const faction = f as 0 | 1;
    let cap = 0;
    for (const b of state.buildings.values()) {
      if (b.faction !== faction || !b.isComplete) continue;
      const bs = BUILDING_FOOTPRINTS; // placeholder, real uses stats but we call in place
    }
    // actual logic moved to sim.ts to avoid circular
  }
}

