  const tx = Math.floor(target.x), ty = Math.floor(target.y);
  if (isTileWalkable(map, tx, ty, buildings) && !isPositionOccupied({ units: new Map(), buildings } as any, tx, ty)) {
    return tileCenter(tx, ty);
