/**
 * Browser entry: wires canvas, input, render loop, and headless sim.
 * Thin layer; all logic in sim/.
 */

import type { PRNG } from './prng';
import { createPRNG, getSeedFromURL } from './prng';
import { createWorld, stepWorld, issueOrder, issueHarvestOrder, startConstruction, enqueueTrain, isPlacementValid, getEntitiesInRect, getUnitAt, getBuildingAt, isDefeated, getSideBuildings } from './sim';
import type { BuildingType, Faction, UnitType } from './constants';
import { ALL_BUILDING_TYPES, ALL_UNIT_TYPES, BUILDING_FOOTPRINTS, BUILDING_STATS, FACTION_NAMES, SIM_TICKS_PER_SECOND, UNIT_STATS } from './constants';
import type { EntityId, Order, Vec2, WorldState } from './types';
import { vec, dist, rectCenter } from './utils';

// UI layout (pure, testable)
export interface HudLayout {
  resourceBar: { x: number; y: number; w: number; h: number };
  minimap: { x: number; y: number; w: number; h: number };
  selectionPanel: { x: number; y: number; w: number; h: number };
  trainButtons: Array<{ type: UnitType; rect: { x: number; y: number; w: number; h: number } }>;
  buildButtons: Array<{ type: BuildingType; rect: { x: number; y: number; w: number; h: number } }>;
}

export function computeHudLayout(viewW: number, viewH: number): HudLayout {
  const barH = 32;
  const mmSize = Math.min(180, Math.floor(viewW * 0.22));
  const selW = 240;
  const selH = 140;

  return {
    resourceBar: { x: 0, y: 0, w: viewW, h: barH },
    minimap: { x: viewW - mmSize - 8, y: barH + 8, w: mmSize, h: mmSize },
    selectionPanel: { x: 8, y: viewH - selH - 8, w: selW, h: selH },
    trainButtons: [],
    buildButtons: [],
  };
}

export function hitTestHud(layout: HudLayout, screenX: number, screenY: number): string | null {
  const r = layout.resourceBar;
  if (screenX >= r.x && screenX < r.x + r.w && screenY >= r.y && screenY < r.y + r.h) return 'resourceBar';
  const m = layout.minimap;
  if (screenX >= m.x && screenX < m.x + m.w && screenY >= m.y && screenY < m.y + m.h) return 'minimap';
  const s = layout.selectionPanel;
  if (screenX >= s.x && screenX < s.x + s.w && screenY >= s.y && screenY < s.y + s.h) return 'selectionPanel';
  return null;
}

const canvas = document.getElementById('game') as HTMLCanvasElement;
const ctx = canvas.getContext('2d', { alpha: true })!;

let WIDTH = canvas.width;
let HEIGHT = canvas.height;

let seed = getSeedFromURL(window.location.search) ?? (Date.now() % 1000000);
let prng: PRNG = createPRNG(seed);
let world: WorldState = createWorld({ seed, playerFaction: 0, level: 0, difficulty: 1, prng: prng.clone() });
let playerFaction: Faction = 0;
let selected: Set<EntityId> = new Set();
let camera = { x: world.map.width / 2 - 12, y: world.map.height / 2 - 8 };
let paused = false;
let speed = 1;
let lastTime = performance.now();
let accum = 0;
const TICK = 1 / SIM_TICKS_PER_SECOND;

let showLevelSelect = true;
let currentLevel = 0;
let unlocked = 1; // levels 0..4

function resize() {
  // keep logical size; css scales
}
resize();

function worldToScreen(wx: number, wy: number): { sx: number; sy: number } {
  const scale = 32; // pixels per tile
  return { sx: (wx - camera.x) * scale, sy: (wy - camera.y) * scale };
}

function screenToWorld(sx: number, sy: number): Vec2 {
  const scale = 32;
  return vec(camera.x + sx / scale, camera.y + sy / scale);
}

function draw() {
  ctx.fillStyle = '#112';
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  const scale = 32;
  const tw = world.map.width;
  const th = world.map.height;

  // terrain + fog
  for (let y = 0; y < th; y++) {
    for (let x = 0; x < tw; x++) {
      const t = world.map.tiles[y][x];
      const { sx, sy } = worldToScreen(x, y);
      if (sx < -scale || sy < -scale || sx > WIDTH || sy > HEIGHT) continue;

      let color = '#3a5';
      if (t === 'dirt') color = '#665';
      if (t === 'forest') color = '#152';
      if (t === 'water') color = '#248';
      if (t === 'rock') color = '#444';
      if (t === 'goldMine') color = '#cc8';
      if (t === 'goldDepleted') color = '#775';
      if (t === 'forestDepleted') color = '#332';

      ctx.fillStyle = color;
      ctx.fillRect(sx, sy, scale, scale);

      const f0 = world.fog[0][y]?.[x] ?? 0;
      if (f0 === 0) {
        ctx.fillStyle = 'rgba(0,0,0,0.95)';
        ctx.fillRect(sx, sy, scale, scale);
      } else if (f0 === 1) {
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        ctx.fillRect(sx, sy, scale, scale);
      }
    }
  }

  // buildings
  for (const b of world.buildings.values()) {
    if (b.faction !== playerFaction) {
      // only draw if visible
      const c = { x: b.footprint.x + b.footprint.w / 2, y: b.footprint.y + b.footprint.h / 2 };
      const f = world.fog[playerFaction][Math.floor(c.y)]?.[Math.floor(c.x)] ?? 0;
      if (f < 2) continue;
    }
    const { sx, sy } = worldToScreen(b.footprint.x, b.footprint.y);
    const bw = b.footprint.w * scale;
    const bh = b.footprint.h * scale;
    ctx.fillStyle = b.faction === playerFaction ? '#48a' : '#a54';
    ctx.fillRect(sx, sy, bw, bh);
    ctx.strokeStyle = '#fff';
    ctx.strokeRect(sx, sy, bw, bh);
    // hp bar
    const hpPct = Math.max(0, b.hp / (BUILDING_STATS[b.faction][b.type].hp));
    ctx.fillStyle = '#0f0';
    ctx.fillRect(sx, sy - 4, bw * hpPct, 3);
  }

  // units
  for (const u of world.units.values()) {
    if (u.faction !== playerFaction) {
      const tx = Math.floor(u.pos.x), ty = Math.floor(u.pos.y);
      if ((world.fog[playerFaction][ty]?.[tx] ?? 0) < 2) continue;
    }
    const { sx, sy } = worldToScreen(u.pos.x - 0.4, u.pos.y - 0.4);
    ctx.fillStyle = u.faction === playerFaction ? '#8cf' : '#f84';
    ctx.fillRect(sx, sy, scale * 0.8, scale * 0.8);
    if (selected.has(u.id)) {
      ctx.strokeStyle = '#ff0';
      ctx.lineWidth = 2;
      ctx.strokeRect(sx - 1, sy - 1, scale * 0.8 + 2, scale * 0.8 + 2);
    }
  }

  // projectiles
  for (const p of world.projectiles.values()) {
    const { sx, sy } = worldToScreen(p.pos.x - 0.1, p.pos.y - 0.1);
    ctx.fillStyle = '#ff0';
    ctx.fillRect(sx, sy, 4, 4);
  }

  // minimap
  const layout = computeHudLayout(WIDTH, HEIGHT);
  const mm = layout.minimap;
  ctx.fillStyle = '#222';
  ctx.fillRect(mm.x, mm.y, mm.w, mm.h);
  const mmScaleX = mm.w / tw;
  const mmScaleY = mm.h / th;
  for (let y = 0; y < th; y += 2) {
    for (let x = 0; x < tw; x += 2) {
      const f = world.fog[playerFaction][y]?.[x] ?? 0;
      let c = '#222';
      const t = world.map.tiles[y][x];
      if (f > 0) {
        if (t === 'water') c = '#135'; else if (t === 'forest') c = '#131'; else c = '#353';
      }
      ctx.fillStyle = c;
      ctx.fillRect(mm.x + x * mmScaleX, mm.y + y * mmScaleY, mmScaleX * 2, mmScaleY * 2);
    }
  }
  // viewport rect
  ctx.strokeStyle = '#ff0';
  const vx = mm.x + (camera.x / tw) * mm.w;
  const vy = mm.y + (camera.y / th) * mm.h;
  const vw = (WIDTH / (tw * scale)) * mm.w;
  const vh = (HEIGHT / (th * scale)) * mm.h;
  ctx.strokeRect(vx, vy, Math.max(4, vw), Math.max(4, vh));

  // resource bar
  ctx.fillStyle = '#222';
  ctx.fillRect(0, 0, WIDTH, 32);
  ctx.fillStyle = '#ff0';
  ctx.font = '14px monospace';
  const res = `GOLD ${Math.floor(world.gold[playerFaction])}   WOOD ${Math.floor(world.wood[playerFaction])}   SUPPLY ${world.supplyUsed[playerFaction]}/${world.supplyCap[playerFaction]}   SEED ${seed}   L${currentLevel + 1}`;
  ctx.fillText(res, 12, 22);

  // selection panel
  const sel = layout.selectionPanel;
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(sel.x, sel.y, sel.w, sel.h);
  ctx.strokeStyle = '#555';
  ctx.strokeRect(sel.x, sel.y, sel.w, sel.h);

  if (selected.size > 0) {
    const firstId = Array.from(selected)[0];
    const u = world.units.get(firstId);
    const b = world.buildings.get(firstId);
    ctx.fillStyle = '#ddd';
    if (u) {
      ctx.fillText(`${u.type.toUpperCase()} HP:${Math.floor(u.hp)}`, sel.x + 8, sel.y + 18);
      // train buttons if townhall/barracks
    }
    if (b && b.isComplete) {
      ctx.fillText(`${b.type} HP:${Math.floor(b.hp)}`, sel.x + 8, sel.y + 18);
    }
  }

  // pause / speed
  ctx.fillStyle = '#fff';
  ctx.fillText(paused ? 'PAUSED' : `${speed}x`, WIDTH - 80, 22);

  if (showLevelSelect) {
    ctx.fillStyle = 'rgba(0,0,0,0.85)';
    ctx.fillRect(100, 80, 400, 300);
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText('WARBAND — LEVEL SELECT', 130, 120);
    for (let i = 0; i < 5; i++) {
      const locked = i >= unlocked;
      ctx.fillStyle = locked ? '#666' : (i === currentLevel ? '#0f0' : '#fff');
      ctx.fillText(`Level ${i + 1} ${locked ? '(locked)' : ''}`, 150, 160 + i * 36);
    }
    ctx.fillStyle = '#ff0';
    ctx.fillText('Click level or SPACE to start', 150, 340);
  }

  // win/lose
  const playerDead = isDefeated(world, playerFaction);
  const aiDead = isDefeated(world, (1 - playerFaction) as Faction);
  if (playerDead || aiDead) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    ctx.fillStyle = aiDead ? '#0f0' : '#f44';
    ctx.font = '32px sans-serif';
    ctx.fillText(aiDead ? 'VICTORY' : 'DEFEAT', WIDTH / 2 - 80, HEIGHT / 2);
    if (aiDead) {
      ctx.fillText('Press N for next level', WIDTH / 2 - 120, HEIGHT / 2 + 50);
    }
  }
}

function stepSim(ticks: number) {
  for (let i = 0; i < ticks; i++) {
    stepWorld(world);
    if (isDefeated(world, playerFaction) || isDefeated(world, (1 - playerFaction) as Faction)) break;
  }
}

function gameLoop(now: number) {
  const delta = Math.min((now - lastTime) / 1000, 0.1);
  lastTime = now;
  if (!paused && !showLevelSelect) {
    accum += delta * speed;
    while (accum >= TICK) {
      stepSim(1);
      accum -= TICK;
    }
  }

  draw();
  requestAnimationFrame(gameLoop);
}

function selectAt(worldPos: Vec2, add: boolean) {
  const id = getUnitAt(world, worldPos) || getBuildingAt(world, worldPos);
  if (!id) {
    if (!add) selected.clear();
    return;
  }
  const ent = world.units.get(id) || world.buildings.get(id);
  if (!ent || ent.faction !== playerFaction) {
    if (!add) selected.clear();
    return;
  }
  if (!add) selected.clear();
  selected.add(id);
}

function boxSelect(a: Vec2, b: Vec2) {
  selected.clear();
  const minx = Math.min(a.x, b.x), maxx = Math.max(a.x, b.x);
  const miny = Math.min(a.y, b.y), maxy = Math.max(a.y, b.y);
  const ids = getEntitiesInRect(world, { x: minx, y: miny, w: maxx - minx, h: maxy - miny }, playerFaction);
  ids.forEach(id => selected.add(id));
}

function issueContextOrder(worldPos: Vec2) {
  if (selected.size === 0) return;
  const ids = Array.from(selected);
  // simple heuristic: enemy -> attack, resource -> harvest, else move
  const tgtU = getUnitAt(world, worldPos);
  if (tgtU) {
    const tu = world.units.get(tgtU)!;
    if (tu.faction !== playerFaction) {
      issueOrder(world, ids, { type: 'attack', targetId: tgtU });
      return;
    }
  }
  const tgtB = getBuildingAt(world, worldPos);
  if (tgtB) {
    const tb = world.buildings.get(tgtB)!;
    if (tb.faction !== playerFaction) {
      issueOrder(world, ids, { type: 'attack', targetId: tgtB });
      return;
    }
    // repair own?
    if (tb.hp < BUILDING_STATS[tb.faction][tb.type].hp * 0.95) {
      for (const id of ids) {
        const u = world.units.get(id);
        if (u && u.type === 'worker') {
          issueOrder(world, [id], { type: 'repair', targetId: tgtB, phase: 'travel', progressTicks: 0 });
        }
      }
      return;
    }
  }
  // harvest if worker and near resource
  const res = world.map.resourceNodes.find(n => dist(n.pos, worldPos) < 1.8 && !n.depleted);
  if (res) {
    const wids = ids.filter(id => world.units.get(id)?.type === 'worker');
    if (wids.length) {
      issueHarvestOrder(world, wids, res.pos, res.type);
      return;
    }
  }
  issueOrder(world, ids, { type: 'move', target: worldPos, path: [], pathIndex: 0, repathAttempts: 0 });
}

// Input
let dragStart: Vec2 | null = null;
let mouseDown = false;

canvas.addEventListener('mousedown', (e) => {
  const rect = canvas.getBoundingClientRect();
  const cx = e.clientX - rect.left;
  const cy = e.clientY - rect.top;
  const layout = computeHudLayout(WIDTH, HEIGHT);
  const hit = hitTestHud(layout, cx, cy);
  if (hit === 'minimap') {
    const mm = layout.minimap;
    const wx = ((cx - mm.x) / mm.w) * world.map.width;
    const wy = ((cy - mm.y) / mm.h) * world.map.height;
    camera.x = wx - 12;
    camera.y = wy - 8;
    return;
  }
  if (hit === 'selectionPanel') {
    // train / build clicks would be here; for minimal, ignore detailed buttons in v1
    return;
  }

  mouseDown = true;
  const wpos = screenToWorld(cx, cy);
  if (e.button === 2) {
    issueContextOrder(wpos);
  } else {
    dragStart = wpos;
    const add = e.shiftKey;
    selectAt(wpos, add);
  }
});

canvas.addEventListener('mousemove', (e) => {
  if (!mouseDown || !dragStart) return;
  const rect = canvas.getBoundingClientRect();
  const cx = e.clientX - rect.left;
  const cy = e.clientY - rect.top;
  const wpos = screenToWorld(cx, cy);
  // live box preview could be drawn but for now ok
});

canvas.addEventListener('mouseup', (e) => {
  mouseDown = false;
  if (!dragStart) return;
  const rect = canvas.getBoundingClientRect();
  const cx = e.clientX - rect.left;
  const cy = e.clientY - rect.top;
  const wpos = screenToWorld(cx, cy);
  if (Math.hypot(wpos.x - dragStart.x, wpos.y - dragStart.y) > 1.0) {
    boxSelect(dragStart, wpos);
  }
  dragStart = null;
});

canvas.addEventListener('contextmenu', (e) => e.preventDefault());

window.addEventListener('keydown', (e) => {
  if (showLevelSelect) {
    if (e.key === ' ' || e.key === 'Enter') {
      showLevelSelect = false;
      startLevel(currentLevel);
    }
    const n = parseInt(e.key, 10);
    if (!isNaN(n) && n >= 1 && n <= 5) {
      if (n - 1 < unlocked) {
        currentLevel = n - 1;
        showLevelSelect = false;
        startLevel(currentLevel);
      }
    }
    return;
  }
  if (e.key === ' ') { paused = !paused; e.preventDefault(); }
  if (e.key === '1' || e.key === '2') speed = parseInt(e.key);
  if (e.key.toLowerCase() === 'n' && isDefeated(world, (1-playerFaction) as Faction)) {
    if (unlocked < 5) unlocked++;
    currentLevel = Math.min(4, currentLevel + 1);
    startLevel(currentLevel);
  }
  if ((e.key === 'r' || e.key === 'R') && selected.size) {
    // rebuild simple
    const workers = Array.from(selected).filter(id => world.units.get(id)?.type === 'worker');
    if (workers.length) {
      // issue build townhall near start (demo)
    }
  }
  // camera
  const step = 4;
  if (e.key === 'ArrowLeft') camera.x -= step;
  if (e.key === 'ArrowRight') camera.x += step;
  if (e.key === 'ArrowUp') camera.y -= step;
  if (e.key === 'ArrowDown') camera.y += step;

  // control groups simple 1-9 (demo: only 1)
  if (e.key >= '1' && e.key <= '9' && e.ctrlKey) {
    // store not implemented for brevity
  }
  if (e.key >= '1' && e.key <= '9' && !e.ctrlKey) {
    // recall not full
  }
});

canvas.addEventListener('wheel', (e) => {
  camera.x += e.deltaX * 0.03;
  camera.y += e.deltaY * 0.03;
});

function startLevel(lvl: number) {
  currentLevel = lvl;
  seed = (seed + lvl * 12345) % 999999999;
  prng = createPRNG(seed);
  const p = prng.clone();
  world = createWorld({ seed, playerFaction: 0, level: lvl, difficulty: Math.min(5, lvl + 1), prng: p });
  selected.clear();
  camera = { x: world.map.startLocations[0].x - 8, y: world.map.startLocations[0].y - 6 };
  paused = false;
  speed = 1;
  showLevelSelect = false;
}

requestAnimationFrame(gameLoop);

// expose for tests
(window as any).__warband = { createWorld, stepWorld, computeHudLayout, hitTestHud, getSeedFromURL };
console.log('Warband loaded. Seed=', seed);

