/**
 * Order execution helpers. Extracted to keep sim.ts < 500 lines.
 */
import type { Building, EntityId, Order, Unit, Vec2, WorldState } from '../types';
import type { Faction } from '../constants';
import { BUILDING_STATS, HARVEST_GOLD_TICKS, HARVEST_WOOD_TICKS, REPATh_ATTEMPT_LIMIT, UNIT_STATS } from '../constants';
import { dist, tileCenter } from '../utils';
import { findPath, pathToNextWaypoint } from '../pathfind';
import { isTileWalkable, isPositionOccupied, findNearestWalkable, getBuildingCenter } from './sim-helpers';

export function updateMovement(u: Unit, speed: number, dt: number, state: WorldState): void {
  const o = u.order;
  if (o.type !== 'move') return;
  if (!o.path || o.path.length === 0 || (o.repathAttempts ?? 0) > REPATh_ATTEMPT_LIMIT) {
    const res = findPath(u.pos, o.target, state.map.width, state.map.height,
      (tx, ty) => isTileWalkable(state.map, tx, ty, state.buildings),
      (tx, ty) => isPositionOccupied(state, tx, ty, u.id)
    );
    o.path = res.path;
    o.pathIndex = 0;
    o.repathAttempts = (o.repathAttempts ?? 0) + 1;
    if (res.path.length === 0) {
      u.order = { type: 'idle' };
      return;
    }
  }
  const wp = pathToNextWaypoint(u.pos, o.path!, o.pathIndex ?? 0, speed, dt);
  u.pos = wp.newPos;
  o.pathIndex = wp.newIndex;
  if (wp.arrived || dist(u.pos, o.target) < 0.7) {
    u.order = { type: 'idle' };
  }
}

export function findNearestResource(state: WorldState, pos: Vec2, type: 'gold' | 'wood'): Vec2 | null {
  let bestD = Infinity;
  let best: Vec2 | null = null;
  for (const n of state.map.resourceNodes) {
    if (n.depleted) continue;
    if (type === 'gold' && n.type !== 'goldMine') continue;
    if (type === 'wood' && n.type !== 'forest') continue;
    const d = dist(pos, n.pos);
    if (d < bestD) { bestD = d; best = n.pos; }
  }
  return best;
}

export function findNearestDropoff(state: WorldState, pos: Vec2, resType: 'gold' | 'wood', faction: Faction): EntityId | null {
  let bestD = Infinity, best: EntityId | null = null;
  for (const [id, b] of state.buildings) {
    if (b.faction !== faction || !b.isComplete) continue;
    const ok = resType === 'gold' ? b.type === 'townHall' : (b.type === 'townHall' || b.type === 'lumberMill');
    if (ok) {
      const d = dist(pos, getBuildingCenter(b));
      if (d < bestD) { bestD = d; best = id; }
    }
  }
  return best;
}

export function updateHarvestOrder(u: Unit, dt: number, state: WorldState): void {
  const o = u.order;
  if (o.type !== 'harvest') return;
  const speed = UNIT_STATS[u.faction][u.type].moveSpeed;
  if (o.phase === 'travel') {
    const d = dist(u.pos, o.sourcePos);
    if (d < 1.2) {
      o.phase = 'gather';
      o.gatherTicksLeft = o.resourceType === 'gold' ? HARVEST_GOLD_TICKS : HARVEST_WOOD_TICKS;
    } else {
      const moved = false; // movement handled outside for simplicity in this extraction
      if (!moved && (o.repathAttempts ?? 0) < REPATh_ATTEMPT_LIMIT) {
        const np = findNearestResource(state, u.pos, o.resourceType);
        if (np) o.sourcePos = np;
        o.repathAttempts = (o.repathAttempts ?? 0) + 1;
      } else if (!moved) {
        u.order = { type: 'idle' };
      }
    }
  } else if (o.phase === 'gather') {
    if (o.gatherTicksLeft !== undefined) o.gatherTicksLeft--;
    if ((o.gatherTicksLeft ?? 0) <= 0) {
      o.carried = o.resourceType === 'gold' ? 10 : 5;
      o.phase = 'return';
      const drop = findNearestDropoff(state, u.pos, o.resourceType, u.faction);
      o.dropOffId = drop ?? undefined;
      if (!drop) {
        u.carriedResource = { type: o.resourceType, amount: o.carried };
        u.order = { type: 'idle' };
      }
    }
  } else if (o.phase === 'return') {
    const drop = o.dropOffId ? state.buildings.get(o.dropOffId) : null;
    if (!drop || !drop.isComplete) {
      const nd = findNearestDropoff(state, u.pos, o.resourceType, u.faction);
      if (nd) o.dropOffId = nd;
      else {
        u.carriedResource = { type: o.resourceType, amount: o.carried };
        u.order = { type: 'idle' };
        return;
      }
    }
    if (drop) {
      if (dist(u.pos, getBuildingCenter(drop)) < 1.7) {
        const amt = o.carried || 10;
        if (o.resourceType === 'gold') state.gold[u.faction] += amt;
        else state.wood[u.faction] += amt;
        o.carried = 0;
        o.phase = 'travel';
        const ns = findNearestResource(state, u.pos, o.resourceType);
        if (ns) o.sourcePos = ns;
        else u.order = { type: 'idle' };
      }
    }
  }
}

export function startBuild(state: WorldState, workerId: EntityId, btype: BuildingType, tx: number, ty: number): boolean {
  const u = state.units.get(workerId);
  if (!u || u.type !== 'worker') return false;
  const fp = BUILDING_FOOTPRINTS[btype];
  const rect = { x: tx, y: ty, w: fp.w, h: fp.h };
  if (!isPlacementValidExternal(state, rect)) return false;
  const costG = BUILDING_STATS[u.faction][btype].goldCost;
  const costW = BUILDING_STATS[u.faction][btype].woodCost;
  if (state.gold[u.faction] < costG || state.wood[u.faction] < costW) return false;
  state.gold[u.faction] -= costG;
  state.wood[u.faction] -= costW;
  const o: Order = { type: 'build', buildingType: btype, footprint: rect, phase: 'travel', progressTicks: 0, targetPos: tileCenter(tx + (fp.w >> 1), ty + (fp.h >> 1)) };
  u.order = o;
  return true;
}

function isPlacementValidExternal(state: WorldState, fp: { x: number; y: number; w: number; h: number }): boolean {
  // delegate or duplicate minimal check
  for (let y = fp.y; y < fp.y + fp.h; y++) {
    for (let x = fp.x; x < fp.x + fp.w; x++) {
      if (!isTileWalkable(state.map, x, y, state.buildings)) return false;
    }
  }
  return true;
}

