content.text:
canvas.addEventListener('mouseup', (e) => {
  mouseDown = false;
  if (!dragStart) return;
  const rect = canvas.getBoundingClientRect();
  const cx = e.clientX - rect.left;
  const cy = e.clientY - rect.top;
  const wpos = screenToWorld(cx, cy);
  if (Math.hypot(wpos.x - dragStart.x, wpos.y - dragStart.y) > 1.0) {
    boxSelect(dragStart, wpos);
  }
  dragStart = null;
});

canvas.addEventListener('contextmenu', (e) => e.preventDefault());

window.addEventListener('keydown', (e) => {
  if (showLevelSelect) {
    if (e.key === ' ' || e.key === 'Enter') {
      showLevelSelect = false;
      startLevel(currentLevel);
    }
    const n = parseInt(e.key, 10);
    if (!isNaN(n) && n >= 1 && n <= 5) {
      if (n - 1 < unlocked) {
        currentLevel = n - 1;
        showLevelSelect = false;
        startLevel(currentLevel);
      }
    }
    return;
  }
  if (e.key === ' ') { paused = !paused; e.preventDefault(); }
  if (e.key === '1' || e.key === '2') speed = parseInt(e.key);
  if (e.key.toLowerCase() === 'n' && isDefeated(world, (1-playerFaction) as Faction)) {
    if (unlocked < 5) unlocked++;
    currentLevel = Math.min(4, currentLevel + 1);
    startLevel(currentLevel);
  }
  if ((e.key === 'r' || e.key === 'R') && selected.size) {
    // rebuild simple
    const workers = Array.from(selected).filter(id => world.units.get(id)?.type === 'worker');
    if (workers.length) {
      // issue build townhall near start (demo)
    }
  }
  // camera
  const step = 4;
  if (e.key === 'ArrowLeft') camera.x -= step;
  if (e.key === 'ArrowRight') camera.x += step;
  if (e.key === 'ArrowUp') camera.y -= step;
  if (e.key === 'ArrowDown') camera.y += step;

  // control groups simple 1-9 (demo: only 1)
  if (e.key >= '1' && e.key <= '9' && e.ctrlKey) {
    // store not implemented for brevity
  }
  if (e.key >= '1' && e.key <= '9' && !e.ctrlKey) {
    // recall not full
  }
});

canvas.addEventListener('wheel', (e) => {
  camera.x += e.deltaX * 0.03;
  camera.y += e.deltaY * 0.03;
});

function startLevel(lvl: number) {
  currentLevel = lvl;
  seed = (seed + lvl * 12345) % 999999999;
  prng = createPRNG(seed);
  const p = prng.clone();
  world = createWorld({ seed, playerFaction: 0, level: lvl, difficulty: Math.min(5, lvl + 1), prng: p });
  selected.clear();
  camera = { x: world.map.startLocations[0].x - 8, y: world.map.startLocations[0].y - 6 };
  paused = false;
  speed = 1;
  showLevelSelect = false;
}

requestAnimationFrame(gameLoop);

// expose for tests
(window as any).__warband = { createWorld, stepWorld, computeHudLayout, hitTestHud, getSeedFromURL };
console.log('Warband loaded. Seed=', seed);

